// pushou: a press button holding a Warring States bronze mask-and-ring handle, photographed by the Freer Gallery
// (F1917.18). Pressing lifts the ring on the bar inside the nose loop; letting go, it swings back against the door,
// and that blow is the knock. The ring is the photograph's own pixels turned as a rigid plane about its hinge; the
// mask never moves.
//
//   <button type="button" class="po" data-pushou>
//     <span class="po-knocker" aria-hidden="true"> <img class="po-plate" ...> <img class="po-ring" ...> <img class="po-loop" ...> </span>
//     <span class="po-label">Ring for service</span>
//   </button>
//
// The button is a real <button>: its click is yours, as usual. `pushou:knock` fires on the button when the ring
// strikes the door after a click (detail: {force 0-1, strike 1 | 2, source 'pointer' | 'keyboard' | 'script'}).
// Options (data- attributes or the options object, which wins): hold (deg the hand lifts it: 24, or 32 on a knocker
// under 48 px), tap (deg for Enter and knock(): 18, or 24 under 48 px), wait (deg wait() holds it at: 11, or 18
// under 48 px), size (cm, the knocker's scale for the swing, 16), bounce (0-1, 0.32).
// Returns a destroy function with knock(), wait(), cancel(), lift() and release() on it.

const RAD = Math.PI / 180;
const G = 981;                      // cm/s^2
const STEP = 1 / 240;
const DOOR = -1.2 * RAD;            // the ring swings a hair past hanging straight before it meets the door
const DAMP = 1.6;                   // air and the hinge while it swings, 1/s
const SETTLE = 9;                   // once it can't reach the door again, the bar's friction takes it, 1/s
const REST = 0.3 * RAD;             // a swing smaller than this is over: the ring hangs as photographed
const MAX = 32 * RAD;               // the most the ring is ever lifted: what the restored plate behind it allows
const BRIEF = 110;                  // ms: a hand that lets go sooner still carries the ring up this long (a tap)
const TOUCH = 90;                   // ms: a finger waits this long before it lifts, in case it is starting a scroll
const SMALL = 48;                   // px: a knocker shorter than this lifts higher and casts a firmer shadow
const live = new WeakMap();
const reduced = typeof matchMedia === 'function' ? matchMedia('(prefers-reduced-motion: reduce)') : { matches: false };

const num = (v, d) => (v === undefined || v === null || v === '' || isNaN(+v) ? d : +v);
const dud = () => Object.assign(() => {}, { knock() {}, wait() {}, cancel() {}, lift() {}, release() {} });

export function pushou(btn, opts = {}) {
  if (!btn) return dud();
  if (live.has(btn)) return live.get(btn);
  const d = btn.dataset;
  const o = { hold: num(d.hold, null), tap: num(d.tap, null), wait: num(d.wait, null), size: num(d.size, 16),
    bounce: num(d.bounce, 0.32), ...opts };
  const knocker = btn.querySelector('.po-knocker');
  const ring = knocker && knocker.querySelector('.po-ring');
  if (!ring) return dud();
  const plate = knocker.querySelector('.po-plate');
  const imgs = [...knocker.querySelectorAll('img')];
  const sizes0 = imgs.map((im) => im.getAttribute('sizes'));

  const w2 = G / Math.max(1, o.size);                  // (g / L) for the ring as a pendulum, 1/s^2
  const KH = (2 * Math.PI / 0.14) ** 2;                // the hand: a stiff, critically damped spring
  const off = [];
  const on = (el, t, f, opt) => { el.addEventListener(t, f, opt); off.push(() => el.removeEventListener(t, f, opt)); };
  const timers = new Set();
  const later = (f, ms) => { const id = setTimeout(() => { timers.delete(id); f(); }, ms); timers.add(id); return id; };
  const stop = (id) => { if (id) { clearTimeout(id); timers.delete(id); } return 0; };

  let th = 0, om = 0;               // lift beyond hanging straight (rad, out from the door is positive), and its rate
  let target = null;                // while a hand holds the ring: the angle it is held at (0: putting it back down)
  let auto = 0;                     // a tap or a scripted knock lets go by itself at this time
  let armed = false, source = 'pointer', strikes = 0, touched = false;
  let pressed = false, keyHeld = false, waiting = false;
  let raf = 0, clock = 0, since = 0, downTimer = 0, tapTimer = 0;
  let visible = true;

  // the shadow the ring casts on the door while it is lifted, from the ring's own outline
  const shade = document.createElement('span');
  shade.className = 'po-shade';
  shade.setAttribute('aria-hidden', 'true');
  knocker.insertBefore(shade, ring);
  // the shadows (this one, and the contact shadows behind the knocker in pushou.css) are cut from the layers' own
  // images: use the files that are showing
  const srcs = () => {
    if (ring.currentSrc) knocker.style.setProperty('--po-ring-src', `url("${ring.currentSrc}")`);
    if (plate && plate.currentSrc) knocker.style.setProperty('--po-plate-src', `url("${plate.currentSrc}")`);
  };
  srcs();
  on(ring, 'load', srcs);
  if (plate) on(plate, 'load', srcs);

  // a backstop for the markup's sizes: if a layer's file was chosen for a width more than 20% off the width it is
  // shown at, choose again. Only then: choosing again lets the browser swap in a larger file it happens to have
  // cached, and the three layers should come from the same file size, as cut.
  let hpx = 40;                                         // the knocker's height, for the perspective and the shadow
  const fit = () => {
    const r = knocker.getBoundingClientRect();
    if (knocker.offsetHeight > 0) hpx = knocker.offsetHeight;
    if (r.width > 0) for (const im of imgs) {
      const chosen = im.complete ? im.naturalWidth : 0;   // with a w-descriptor srcset: the sizes width it was chosen for
      if (im.srcset && chosen && Math.abs(chosen - r.width) > r.width * 0.2) im.sizes = Math.ceil(r.width) + 'px';
    }
  };
  fit();
  for (const im of imgs) on(im, 'load', fit);
  const ro = typeof ResizeObserver === 'function' ? new ResizeObserver(fit) : null;
  if (ro) ro.observe(knocker);
  const holdDeg = () => o.hold ?? (hpx < SMALL ? 32 : 24);
  const tapDeg = () => o.tap ?? (hpx < SMALL ? 24 : 18);
  const waitDeg = () => o.wait ?? (hpx < SMALL ? 18 : 11);
  const omRef = (deg) => Math.sqrt(Math.max(1e-6, 2 * w2 * (Math.cos(DOOR) - Math.cos(deg * RAD))));
  const amp = () => Math.sqrt(th * th + (om * om) / w2);  // how far this swing will carry the ring (rad)

  function draw() {
    if (Math.abs(th) < 1e-4) {
      ring.style.transform = '';
      shade.style.opacity = shade.style.transform = shade.style.filter = '';
      knocker.style.removeProperty('--po-lift');
      return;
    }
    const h = hpx, s = Math.max(0, Math.sin(th));
    ring.style.transform = `perspective(${(h * 3.6).toFixed(1)}px) rotateX(${(th / RAD).toFixed(3)}deg)`;
    // its shadow leaves the door with it: further, softer and darker the higher it is lifted. On a small knocker it
    // has a floor (1.5 px, 0.42, sharp), so that a lifted ring is seen to leave the door
    let op = 0.34 * Math.min(1, s * 2.2), dy = h * 0.075 * s, blur = h * (0.004 + 0.03 * s);
    if (h < SMALL) {
      const k = Math.min(1, s / 0.21);                    // full by about 12 degrees
      op = Math.max(op, 0.42 * k); dy = Math.max(dy, 1.5 * k); blur = Math.min(blur, 0.8);
    }
    shade.style.opacity = op.toFixed(3);
    shade.style.transform = `translateY(${dy.toFixed(2)}px) scaleY(${Math.cos(th * 0.8).toFixed(4)})`;
    shade.style.filter = `blur(${blur.toFixed(2)}px)`;
    knocker.style.setProperty('--po-lift', Math.min(1, s / 0.14).toFixed(3));   // its contact shadow lets go of it
  }

  const emit = (force, n) => btn.dispatchEvent(new CustomEvent('pushou:knock',
    { bubbles: true, detail: { force: +force.toFixed(3), strike: n, source } }));
  function strike(v) {
    strikes += 1;
    const force = Math.min(1, Math.abs(v) / omRef(Math.max(holdDeg(), tapDeg())));
    if (armed && force > 0.06 && strikes <= 2) emit(force, strikes);
  }

  function step(dt, now) {
    if (target !== null) {
      om += (KH * (target - th) - 2 * Math.sqrt(KH) * om) * dt;
      th = Math.min(MAX, th + om * dt);
      if (auto && now >= auto) { target = null; auto = 0; }
      return;
    }
    const settling = strikes >= 2 || touched || (strikes >= 1 && amp() < -DOOR);
    om += (-w2 * Math.sin(th) - (settling ? SETTLE : DAMP) * om) * dt;
    th += om * dt;
    if (th > MAX) { th = MAX; if (om > 0) om = 0; }        // the band's top meets the plate behind it
    if (th < DOOR) {
      th = DOOR;
      if (om < -0.35) { strike(om); om = -om * o.bounce; }
      else { om = 0; touched = true; }
    }
  }
  function settle() {               // at rest: the photograph, untouched
    th = 0; om = 0; target = null; auto = 0; strikes = 0; armed = false; touched = false;
    draw();
  }

  // time comes from the clock, not from frames: after a stalled frame the world catches up (up to half a second)
  function frame(now) {
    raf = 0;
    if (now - clock > 500) clock = now - 500;
    while (clock + STEP * 1000 <= now) { step(STEP, clock); clock += STEP * 1000; }
    if (target === null ? amp() < REST : !auto && Math.abs(target - th) < 1e-3 && Math.abs(om) < 1e-2) {
      if (target === null || target === 0) settle();
      else { th = target; om = 0; draw(); }               // held still: nothing moves, so nothing runs
      return;
    }
    draw();
    raf = requestAnimationFrame(frame);
  }
  // off screen nothing is animated: what the ring was about to do is done at once
  function jump() {
    if (raf) { cancelAnimationFrame(raf); raf = 0; }
    if (target !== null && auto) { th = Math.max(th, target); om = 0; target = null; auto = 0; }   // it lets go now
    if (target !== null && target !== 0) { th = target; om = 0; draw(); return; }                   // still held
    if (target === null && armed && strikes === 0 && th > 0) {    // the knock that was coming lands now, as hard
      strike(-0.83 * Math.sqrt(om * om + 2 * w2 * (Math.cos(DOOR) - Math.cos(th))));               // as it would have
    }
    settle();
  }
  const wake = () => {
    if (!visible) { jump(); return; }
    if (!raf) { clock = performance.now(); raf = requestAnimationFrame(frame); }
  };
  const inert = () => btn.disabled || btn.getAttribute('aria-disabled') === 'true';

  function lift(deg = holdDeg(), src = 'script') {
    if (inert() || reduced.matches) return;
    source = src;
    strikes = 0; touched = false;
    if (target === null) since = performance.now();
    target = Math.min(MAX, Math.max(0, deg * RAD));      // the cut allows up to 32 deg (see tools/parts.py)
    wake();
  }
  function release() {
    if (target === null) return;
    const held = performance.now() - since;
    if (held < BRIEF) { auto = since + BRIEF; wake(); return; }   // a tap: finish the lift, then let go
    target = null; auto = 0;
    wake();
  }
  function lower() {                // the hand puts the ring back against the door: it doesn't fall, so no knock
    armed = false; auto = 0;
    if (reduced.matches || (target === null && Math.abs(th) < 1e-4)) return;
    target = 0;
    wake();
  }
  const unbusy = () => { if (waiting) { waiting = false; btn.removeAttribute('aria-busy'); } };
  // while the app works on what the click asked for, the hand holds the ring a little way up, still
  function wait(deg = waitDeg()) {
    if (inert()) return;
    waiting = true; armed = false; auto = 0;
    btn.setAttribute('aria-busy', 'true');
    if (reduced.matches) return;
    if (target === null) since = performance.now();
    strikes = 0; touched = false;
    target = Math.min(MAX, Math.max(0, deg * RAD));
    wake();
  }
  function cancel() { unbusy(); lower(); }
  function knock(src = 'script') {
    if (inert()) return;
    const held = waiting;
    unbusy();
    armed = true; source = src;
    if (reduced.matches) {          // nothing moves: the knock is the event alone (after the click's other listeners,
      later(() => { if (armed) { armed = false; emit(1, 1); } }, 0);   // so that one of them can still wait())
      return;
    }
    if (held || target === 0 || (target === null && th < 0.05)) {   // lift it a little higher from where it is, and let go
      since = performance.now();
      strikes = 0; touched = false;
      target = Math.min(MAX, Math.max(th, tapDeg() * RAD));
      auto = since + BRIEF;
      wake();
    }
  }

  // pointer: the hand lifts the ring while it presses, and lets go on release
  function press() { btn.classList.add('po-press'); lift(holdDeg(), 'pointer'); }
  on(btn, 'pointerdown', (e) => {
    if (e.button !== 0 || !e.isPrimary || inert() || waiting) return;
    pressed = true;
    tapTimer = stop(tapTimer);
    if (e.pointerType === 'mouse') press();
    else downTimer = later(() => { downTimer = 0; press(); }, TOUCH);   // a finger may be starting a scroll
  });
  // is the pointer over the button (its own touch target included)? A press let go anywhere else doesn't click
  const over = (e) => {
    if (!e || !Number.isFinite(e.clientX)) return false;
    const el = document.elementFromPoint(e.clientX, e.clientY);
    return !!el && btn.contains(el);
  };
  const up = (e) => {
    if (!pressed) return;
    pressed = false;
    const onIt = over(e);
    if (downTimer) {                // a quick tap: lift now, and let go as soon as the lift is done
      downTimer = stop(downTimer);
      if (inert() || waiting || !onIt) return;
      press();
      tapTimer = later(() => { tapTimer = 0; btn.classList.remove('po-press'); }, BRIEF);
    } else btn.classList.remove('po-press');
    if (onIt) release();
    else lower();                   // slid off and let go: the click is off, so the hand puts the ring back down
  };
  const abandon = () => {           // it was a scroll after all, or the window lost the press: no knock
    if (!pressed) return;
    pressed = false;
    if (downTimer) { downTimer = stop(downTimer); return; }
    btn.classList.remove('po-press');
    lower();
  };
  on(btn, 'pointerup', up);
  on(btn, 'pointercancel', abandon);
  on(btn, 'pointerleave', (e) => { if (!e.buttons) up(null); });   // let go out of our sight: no click
  on(window, 'pointerup', up);      // a hand still pressing keeps hold of the ring: let go on the button, it knocks
  // keyboard: Space holds it up until the key comes up (the button clicks then); Enter clicks at once
  const unkey = () => { if (keyHeld) { keyHeld = false; btn.classList.remove('po-press'); lower(); } };
  on(window, 'blur', () => { abandon(); unkey(); });
  on(btn, 'keydown', (e) => {
    if (e.key !== ' ' || e.repeat || inert() || waiting) return;
    keyHeld = true;
    btn.classList.add('po-press');
    lift(holdDeg(), 'keyboard');
  });
  on(btn, 'keyup', (e) => {
    if (e.key !== ' ' || !keyHeld) return;
    keyHeld = false;
    btn.classList.remove('po-press');
    release();
  });
  on(btn, 'blur', unkey);
  // the click: the knock that follows it is reported; a scripted or Enter click lifts the ring itself. Captured, so
  // that it runs before your own click listeners on the button: an aria-disabled or waiting button doesn't click
  on(btn, 'click', (e) => {
    if (btn.getAttribute('aria-disabled') === 'true' || waiting) {
      e.preventDefault(); e.stopImmediatePropagation();
      return;
    }
    if (btn.disabled) return;
    const src = e.detail === 0 ? (source === 'keyboard' || document.activeElement === btn ? 'keyboard' : 'script') : 'pointer';
    const aloft = (target !== null && target !== 0) || (target === null && th > 0.05);   // a hand has it up, or it is falling
    if (aloft) { armed = true; source = src === 'script' ? source : src; return; }
    knock(src);
  }, true);

  // cheap when idle: off screen, the loop doesn't run
  const io = typeof IntersectionObserver === 'function' ? new IntersectionObserver((es) => {
    visible = es[es.length - 1].isIntersecting;
    if (!visible) { if (raf) jump(); }
    else if (target !== null ? auto || Math.abs(target - th) > 1e-3 : Math.abs(th) > 1e-4) wake();
  }) : null;
  if (io) io.observe(knocker);

  btn.dataset.poReady = '';
  draw();

  function destroy() {
    off.forEach((f) => f());
    timers.forEach((id) => clearTimeout(id)); timers.clear();
    if (raf) cancelAnimationFrame(raf);
    raf = 0;
    if (ro) ro.disconnect();
    if (io) io.disconnect();
    shade.remove();
    ring.style.transform = '';
    for (const p of ['--po-ring-src', '--po-plate-src', '--po-lift']) knocker.style.removeProperty(p);
    for (const el of [ring, knocker]) if (el.getAttribute('style') === '') el.removeAttribute('style');
    imgs.forEach((im, i) => (sizes0[i] === null ? im.removeAttribute('sizes') : im.setAttribute('sizes', sizes0[i])));
    unbusy();
    btn.classList.remove('po-press');
    delete btn.dataset.poReady;
    live.delete(btn);
  }
  const api = Object.assign(destroy, {
    knock: () => knock('script'),
    wait: (deg) => wait(deg ?? waitDeg()),
    cancel,
    lift: (deg) => lift(deg ?? holdDeg(), 'script'),
    release,
  });
  Object.defineProperty(api, 'angle', { get: () => th / RAD });   // degrees out from hanging straight
  Object.defineProperty(api, 'waiting', { get: () => waiting });
  live.set(btn, api);
  return api;
}

function start() {
  document.querySelectorAll('[data-pushou]').forEach((el) => pushou(el));
}
if (typeof document !== 'undefined') {
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start, { once: true });
  else start();
}

// sound.js: plays this component's sounds (sounds.json beside it) at the moments they are wired to.
// Copied into a component by the viewer's Sound panel (tools/sound/studio.py); edit sounds.json, not this file.
//
// Off until the visitor turns it on: a small speaker button (sounds.json "toggle": false hides it, then call
// setSound(true) from your own control). The choice is remembered per site in localStorage "sf-sound".
//
// sounds.json: { "toggle": true, "sounds": [ { "name", "file", "on", "target", "volume", "vary", "once" } ] }
//   on      press | release | click | drag | hover | enter | key | load | event:<name>
//   target  a CSS selector the moment happens on ("body" = anywhere)
//   volume  0-1      vary  random pitch, +- semitones      once  only the first time
//   match   with event:<name>, only when the event's detail has these values, e.g. { "state": "mended" }
//   cooldown  ms before the same sound can play again (default 50)
//
// Exports sound(opts) -> { destroy } and setSound(on). Auto-starts when loaded, once per copy of this file.

const KEY = 'sf-sound';
const BASE = new URL('.', import.meta.url);
const listeners = new Set();

function stored() { try { return localStorage.getItem(KEY) === 'on'; } catch { return false; } }
export function setSound(on) {
  try { localStorage.setItem(KEY, on ? 'on' : 'off'); } catch {}
  listeners.forEach((f) => f(on));
  window.dispatchEvent(new CustomEvent('sf-sound', { detail: on }));   // other copies on the page
}

export function sound(opts = {}) {
  const off = [];
  const listen = (el, type, fn, o) => { el.addEventListener(type, fn, o); off.push(() => el.removeEventListener(type, fn, o)); };
  let ctx = null, cfg = null, enabled = stored(), dead = false, button = null;
  const buffers = new Map(), last = new Map(), played = new Set();

  function audio() {
    if (!ctx) {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return null;
      ctx = new AC();
      for (const s of cfg.sounds) load(s);
    }
    if (ctx.state === 'suspended') ctx.resume();
    return ctx;
  }
  async function load(s) {
    if (buffers.has(s.name)) return;
    buffers.set(s.name, null);
    try {
      const r = await fetch(new URL(s.file, BASE));
      buffers.set(s.name, await ctx.decodeAudioData(await r.arrayBuffer()));
      if (s.on === 'load') play(s);
    } catch { buffers.delete(s.name); }
  }
  function play(s) {
    if (!enabled || dead) return;
    if (s.once && played.has(s.name)) return;
    const now = performance.now();
    if (now - (last.get(s.name) || 0) < (s.cooldown ?? 50)) return;
    const c = audio(), buf = c && buffers.get(s.name);
    if (!buf) return;
    last.set(s.name, now); played.add(s.name);
    const src = c.createBufferSource(), g = c.createGain();
    src.buffer = buf;
    if (s.vary) src.playbackRate.value = 2 ** (((Math.random() * 2 - 1) * s.vary) / 12);
    g.gain.value = s.volume ?? 0.8;
    src.connect(g).connect(c.destination);
    src.start();
  }

  const within = (e, sel) => e.target instanceof Element && (sel === 'body' ? e.target : e.target.closest(sel));

  function bind(s) {
    const sel = s.target || 'body';
    const on = s.on || 'press';
    if (on === 'press') listen(document, 'pointerdown', (e) => within(e, sel) && play(s));
    else if (on === 'click') listen(document, 'click', (e) => within(e, sel) && play(s));
    else if (on === 'release') {
      let down = false;
      listen(document, 'pointerdown', (e) => { down = !!within(e, sel); });
      listen(document, 'pointerup', () => { if (down) play(s); down = false; });
    } else if (on === 'drag') {
      let start = null;
      listen(document, 'pointerdown', (e) => { start = within(e, sel) ? { x: e.clientX, y: e.clientY, fired: false } : null; });
      listen(document, 'pointermove', (e) => {
        if (start && !start.fired && Math.hypot(e.clientX - start.x, e.clientY - start.y) > 6) { start.fired = true; play(s); }
      });
      const end = () => { start = null; };
      listen(document, 'pointerup', end); listen(document, 'pointercancel', end);
    } else if (on === 'hover') {
      listen(document, 'pointerover', (e) => {
        const el = e.pointerType === 'mouse' && within(e, sel);
        if (el && !(e.relatedTarget instanceof Node && el.contains(e.relatedTarget))) play(s);
      });
    } else if (on === 'enter') {
      const seen = new WeakSet();
      const io = new IntersectionObserver((es) => es.forEach((en) => {
        if (en.isIntersecting && !seen.has(en.target)) { seen.add(en.target); play(s); }
        else if (!en.isIntersecting) seen.delete(en.target);
      }), { threshold: 0.35 });
      document.querySelectorAll(sel).forEach((el) => io.observe(el));
      off.push(() => io.disconnect());
    } else if (on === 'key') {
      listen(document, 'keydown', (e) => {
        if (e.repeat || e.metaKey || e.ctrlKey || e.altKey || e.key.length > 1 && !/^(Enter| |Backspace)$/.test(e.key)) return;
        if (sel === 'body' || document.activeElement?.closest(sel)) play(s);
      });
    } else if (on === 'load') {
      s.once = true;
      const tryPlay = () => play(s);
      listeners.add(tryPlay); off.push(() => listeners.delete(tryPlay));
      tryPlay();
    } else if (on.startsWith('event:')) {
      const want = s.match ? Object.entries(s.match) : [];
      const fits = (e) => want.every(([k, v]) => e.detail?.[k] === v);
      listen(document, on.slice(6), (e) => (sel === 'body' || within(e, sel)) && fits(e) && play(s), true);
    }
  }

  // the first touch or key after sound is on is what lets a browser start audio
  const unlock = () => { if (enabled && cfg) { audio(); listeners.forEach((f) => f(true)); } };
  listen(document, 'pointerdown', unlock, true);
  listen(document, 'keydown', unlock, true);
  const sync = (on) => {
    enabled = on;
    if (button) { button.setAttribute('aria-pressed', String(on)); button.setAttribute('aria-label', on ? 'Sound on' : 'Sound off'); }
    if (on && cfg) audio();
  };
  listeners.add(sync); off.push(() => listeners.delete(sync));
  listen(window, 'storage', (e) => { if (e.key === KEY) sync(stored()); });
  listen(window, 'sf-sound', (e) => { if (e.detail !== enabled) sync(e.detail); });

  function addButton() {
    if (!document.getElementById('sfs-style')) {
      const st = document.createElement('style'); st.id = 'sfs-style';
      st.textContent = `.sfs-toggle{position:fixed;right:max(14px,env(safe-area-inset-right));bottom:max(14px,env(safe-area-inset-bottom));z-index:2147483000;
        width:36px;height:36px;border-radius:50%;border:1px solid var(--rule,#cfcac0);background:var(--paper,#f3f0e8);color:var(--ink-2,#4a4744);
        display:grid;place-items:center;cursor:pointer;padding:0;opacity:.82;transition:opacity .3s,background .3s,color .3s}
        .sfs-toggle:hover{opacity:1}.sfs-toggle[aria-pressed=true]{background:var(--ink,#141312);color:var(--paper,#f3f0e8);border-color:var(--ink,#141312)}
        .sfs-toggle:focus-visible{outline:2px solid var(--accent,#c96f4a);outline-offset:2px}
        .sfs-toggle svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}
        .sfs-toggle .w{transition:opacity .3s}.sfs-toggle[aria-pressed=false] .w{opacity:0}.sfs-toggle[aria-pressed=true] .x{opacity:0}`;
      document.head.append(st);
    }
    button = document.createElement('button');
    button.type = 'button'; button.className = 'sfs-toggle'; button.title = 'Sound';
    button.innerHTML = '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M2.5 6h2.2L8 3.2v9.6L4.7 10H2.5z"/>' +
      '<path class="w" d="M10.6 5.6a3.4 3.4 0 0 1 0 4.8M12.4 3.8a6 6 0 0 1 0 8.4"/><path class="x" d="M10.5 6.2l3.2 3.6M13.7 6.2l-3.2 3.6"/></svg>';
    button.addEventListener('click', () => setSound(!enabled));
    document.body.append(button);
    off.push(() => button.remove());
    sync(enabled);
  }

  (async () => {
    try {
      cfg = opts.config || await (await fetch(new URL('sounds.json', BASE), { cache: 'no-store' })).json();
    } catch { return; }
    if (dead || !cfg.sounds?.length) return;
    cfg.sounds.forEach(bind);
    if (cfg.toggle !== false && !document.querySelector('.sfs-toggle')) addButton();
    if (enabled) audio();
  })();

  return { destroy() { dead = true; off.forEach((f) => f()); off.length = 0; ctx?.close(); } };
}

// one runtime per copy, so two components with sounds can share a page
const running = (window.__sfSounds ||= {});
if (!running[BASE.href]) running[BASE.href] = window.__sfSound = sound();

/* pushou: a press button holding a Warring States bronze mask-and-ring handle (Freer F1917.18). Prefixed .po-.
 * The knocker is three layers of one photograph: the plate (the mask), the ring, and the nose loop in front of it.
 * Pressing lifts the ring on its hinge (the bar inside the loop); letting go, it falls back against the door.
 * Sizes: .po-xs (32px), .po-sm (40px, a row button), the default (48px), .po-lg (64px), .po-icon (round, no words),
 * .po-hero (a large tile: the knocker, the words under it). .po-solid for a primary button in ink. .po-done, with
 * aria-disabled="true", for an action that has been done. Theme with --paper, --ink, --ink-2, --ink-3, --rule,
 * --sans, and --po-h (the height; the knocker follows it).                                                      */

.po {
    --po-h: 48px;                                   /* the button's height */
    --po-size: calc(var(--po-h) - 8px);             /* the knocker's height */
    --po-face: var(--po-paper, var(--paper, #f3f0e8));
    --po-edge: var(--rule, #cfcac0);
    --po-hinge: 44.965%;                            /* the bar the ring hangs on, from the top of the knocker */
    --po-ring-x: 52.56%;                            /* the ring's centre, from the left */
    --po-shadow: rgb(28, 20, 12);                   /* the knocker's shadows on the door */
    --po-contact: .3;
    position: relative;
    box-sizing: border-box;
    display: inline-flex; align-items: center; gap: .62em;
    min-height: var(--po-h);
    /* the knocker sits in the pill's round end, a 32nd of the height right of centre and a 64th below it (in
       .po-knocker), so that its top ear clears the border by more than a pixel at every size */
    padding: 0 20px 0 calc((var(--po-h) - var(--po-size) * 0.6976) / 2 + var(--po-h) / 32);
    margin: 0;
    font: 500 14px/1.2 var(--sans, Inter, system-ui, sans-serif);
    letter-spacing: .01em;
    color: var(--ink, #141312);
    background: var(--po-face);
    border: 1px solid var(--po-edge);
    border-radius: 999px;
    cursor: pointer;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
    -webkit-touch-callout: none;
    -webkit-user-select: none; user-select: none;
    transition: border-color .2s ease, color .2s ease, background-color .2s ease;
}
@media (hover: hover) { .po:hover:not(:disabled):not([aria-disabled=true]) { --po-edge: var(--ink-3, #8a857d); } }
.po:focus-visible { outline: 2px solid var(--ink-2, #4a4744); outline-offset: 3px; }
/* pressed. With the script it is .po-press, so that a finger starting a scroll doesn't flash it; without, :active */
.po:not([data-po-ready]):active:not(:disabled):not([aria-disabled=true]),
.po.po-press:not(:disabled):not([aria-disabled=true]) {
    --po-face: color-mix(in srgb, var(--ink, #141312) 4%, var(--po-paper, var(--paper, #f3f0e8)));
    --po-edge: var(--ink-3, #8a857d);
}
.po[aria-busy=true] { cursor: progress; }

/* the knocker: three images of the same canvas, stacked */
.po-knocker {
    position: relative; z-index: 0; display: block; flex: none; top: calc(var(--po-h) / 64);
    height: var(--po-size); aspect-ratio: 842 / 1207;
}
.po-knocker > img, .po-shade {
    position: absolute; inset: 0; width: 100%; height: 100%;
    display: block; margin: 0; max-width: none;
    pointer-events: none; -webkit-user-drag: none; user-select: none;
}
.po-ring { transform-origin: var(--po-ring-x) var(--po-hinge); backface-visibility: hidden; }
/* it sits on the door: a contact shadow under the mask (::before) and one under the ring (::after), cut from their
   own outlines and drawn behind them, so that no filter ever touches the photograph. The ring's lets go of it as
   it lifts (--po-lift, from the script), and its cast shadow (.po-shade) takes over. */
.po-knocker::before, .po-knocker::after {
    content: ""; position: absolute; inset: 0; z-index: -1; pointer-events: none;
    background: var(--po-shadow);
    -webkit-mask: var(--po-plate-src, url("assets/plate-168.webp")) center / 100% 100% no-repeat;
    mask: var(--po-plate-src, url("assets/plate-168.webp")) center / 100% 100% no-repeat;
    opacity: var(--po-contact);
    transform: translateY(max(.6px, calc(var(--po-size) * .016)));
    filter: blur(max(.35px, calc(var(--po-size) * .014)));
}
.po-knocker::after {
    -webkit-mask-image: var(--po-ring-src, url("assets/ring-168.webp"));
    mask-image: var(--po-ring-src, url("assets/ring-168.webp"));
    opacity: calc(var(--po-contact) * (1 - var(--po-lift, 0)));
}
/* while the ring is lifted, its shadow falls on the door under it (made by the script from the ring's own outline) */
.po-shade {
    background: var(--po-shadow);
    -webkit-mask: var(--po-ring-src, url("assets/ring-168.webp")) center / 100% 100% no-repeat;
    mask: var(--po-ring-src, url("assets/ring-168.webp")) center / 100% 100% no-repeat;
    transform-origin: var(--po-ring-x) var(--po-hinge);
    opacity: 0;
}

/* without the script the button still knocks: :active holds the ring up, and it drops when you let go */
@media (prefers-reduced-motion: no-preference) {
    .po:not([data-po-ready]) .po-ring { transition: transform .26s cubic-bezier(.55, 0, .9, .45); }
    .po:not([data-po-ready]):active:not(:disabled):not([aria-disabled=true]) .po-ring {
        transform: perspective(calc(var(--po-size) * 3.6)) rotateX(22deg);
        transition: transform .12s cubic-bezier(.2, .7, .3, 1);
    }
}

.po-label { white-space: nowrap; }
/* words that change (Request access, Requesting…, Requested): each wording in its own span, all but the one showing
   [hidden]. They share one place, so the pill keeps the width of the longest and the knocker doesn't move when the
   words do. The wording marked data-po-done carries the done tick all the time, so the tick's room is kept too. */
.po-label:has(> [hidden]) { display: grid; justify-items: start; }
.po-label:has(> [hidden]) > * { grid-area: 1 / 1; }
.po-label:has(> [hidden]) > [hidden] { display: block; visibility: hidden; }
.po-label:has(> [hidden]) > [data-po-done]::after { content: "\2713"; content: "\2713" / ""; margin-left: .38em; }

/* unavailable: the bronze goes grey and the ring stays down */
.po:disabled, .po[aria-disabled=true] { cursor: not-allowed; color: var(--ink-3, #8a857d); --po-edge: color-mix(in srgb, var(--rule, #cfcac0) 70%, transparent); }
.po:disabled .po-knocker, .po[aria-disabled=true] .po-knocker { filter: grayscale(1) contrast(.85) brightness(1.08); opacity: .5; }

/* ---- sizes: each knocker follows --po-h ---- */
.po-xs { --po-h: 32px; --po-size: calc(var(--po-h) - 6px); padding-right: 12px; gap: .42em; font-size: 12.5px; letter-spacing: .012em; }
.po-xs::before { content: ""; position: absolute; inset: -7px -3px; }      /* a 44 px touch target round a 32 px pill */
.po-sm { --po-h: 40px; --po-size: calc(var(--po-h) - 7px); padding-right: 15px; gap: .5em; font-size: 13px; }
.po-lg { --po-h: 64px; --po-size: calc(var(--po-h) - 10px); padding-right: 28px; gap: .72em; font-size: 16px; letter-spacing: .005em; }
.po-block { display: flex; width: 100%; justify-content: center; }

/* a round button with no words: give it aria-label (and a visible label nearby, or a title) */
.po-icon {
    --po-h: 44px; --po-size: calc(var(--po-h) - 12px);
    width: var(--po-h); flex-shrink: 0; padding: 0; justify-content: center; gap: 0;
}
.po-icon .po-label { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/* the knocker large in a tile, the words under it: the one action of a panel */
.po-hero {
    --po-size: clamp(180px, 34vw, 280px);
    flex-direction: column; gap: clamp(12px, 1.6vw, 16px);
    min-height: 0;
    padding: clamp(20px, 3vw, 30px) clamp(30px, 4.4vw, 48px) clamp(15px, 2vw, 19px);
    border-radius: 12px;
    font-size: 15px;
}
.po-hero .po-knocker { top: 0; }
.po-hero .po-label:has(> [hidden]) { justify-items: center; }
@media (hover: hover) {
    .po-hero:hover:where(:not(:disabled):not([aria-disabled=true])) {
        --po-face: color-mix(in srgb, var(--ink, #141312) 2%, var(--po-paper, var(--paper, #f3f0e8)));
    }
}

/* ---- the primary, in ink ---- */
.po-solid { --po-paper: var(--ink, #141312); --po-edge: var(--ink, #141312); --po-shadow: #000; --po-contact: .55; color: var(--paper, #f3f0e8); }
@media (hover: hover) {
    .po-solid:hover:not(:disabled):not([aria-disabled=true]) { --po-edge: var(--ink, #141312); --po-paper: color-mix(in srgb, var(--paper, #f3f0e8) 9%, var(--ink, #141312)); }
}
/* pressed, the ink takes a little of the words' paper, as the light pill takes a little ink: a step that shows from
   rest on a phone as well as from hover */
.po-solid:not([data-po-ready]):active:not(:disabled):not([aria-disabled=true]),
.po-solid.po-press:not(:disabled):not([aria-disabled=true]) {
    --po-face: color-mix(in srgb, var(--paper, #f3f0e8) 14%, var(--ink, #141312));
    --po-edge: color-mix(in srgb, var(--paper, #f3f0e8) 14%, var(--ink, #141312));
}
/* a primary that is unavailable steps back onto the paper, so its grey bronze still reads */
.po-solid:disabled, .po-solid[aria-disabled=true] {
    --po-paper: color-mix(in srgb, var(--ink, #141312) 7%, var(--paper, #f3f0e8));
    --po-edge: color-mix(in srgb, var(--ink, #141312) 7%, var(--paper, #f3f0e8));
    --po-shadow: rgb(28, 20, 12); --po-contact: .3;
    color: var(--ink-3, #8a857d);
}

/* done: the action has happened. With aria-disabled="true" it keeps focus and doesn't click again. The bronze keeps
   its colour, the ring at rest, and the words step back to ink-2 on the paper (a primary leaves its ink) */
.po.po-done[aria-disabled=true] { cursor: default; color: var(--ink-2, #4a4744); --po-edge: var(--rule, #cfcac0); }
.po.po-done[aria-disabled=true] .po-knocker { filter: none; opacity: 1; }
.po.po-done[aria-disabled=true] .po-label::after { content: "\2713"; content: "\2713" / ""; margin-left: .38em; }  /* not read aloud */
.po.po-done[aria-disabled=true] .po-label:has(> [hidden])::after { content: none; }   /* words that change carry their own */
.po-solid.po-done[aria-disabled=true] { --po-paper: inherit; --po-shadow: rgb(28, 20, 12); --po-contact: .3; }

@media (forced-colors: active) {
    .po { border-color: ButtonText; }
    .po:disabled, .po[aria-disabled=true] { border-color: GrayText; }
    .po-knocker::before, .po-knocker::after, .po-shade { display: none; }
}
